<?php
// Legacy payout refund reason retained for audit compatibility: settlement_reject_refund
// مدل فعال این نسخه: واریز نماینده به ادمین و افزایش اعتبار پس از تأیید.
declare(strict_types=1);if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/../botapi.php';require_once __DIR__.'/../lib/PersianDate.php';require_once __DIR__.'/lib/icons.php';
$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$admin=$q->fetch(PDO::FETCH_ASSOC);$q->closeCursor();if(!$admin){header('Location:login.php');exit;}if(($admin['rule']??'')!=='administrator'){http_response_code(403);exit;}
try{rx_require_schema($pdo,['reseller_deposit_requests','reseller_wallet_ledger']);}catch(Throwable$e){header('Location:migrations.php?required=reseller_deposits');exit;}
$flash='';$ft='success';$labels=['pending'=>'در انتظار بررسی','approved'=>'تأیید و شارژ شد','rejected'=>'رد شده','cancelled'=>'لغوشده'];
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{$act=(string)($_POST['action']??'');$id=(string)($_POST['request_id']??'');if(!in_array($act,['approve','reject'],true))throw new RuntimeException('عملیات نامعتبر است.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM reseller_deposit_requests WHERE request_id=? FOR UPDATE');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);$q->closeCursor();if(!$r||$r['status']!=='pending')throw new RuntimeException('درخواست قبلاً بررسی شده یا وجود ندارد.');$note=mb_substr(trim((string)($_POST['admin_note']??'')),0,1000);if($act==='approve'){$u=$pdo->prepare('UPDATE user SET Balance=Balance+? WHERE id COLLATE utf8mb4_unicode_ci = ? COLLATE utf8mb4_unicode_ci');$u->execute([(int)$r['amount'],(string)$r['reseller_id']]);if($u->rowCount()!==1)throw new RuntimeException('حساب نماینده پیدا نشد.');$pdo->prepare("UPDATE reseller_deposit_requests SET status='approved',reviewed_at=?,reviewed_by=?,admin_note=? WHERE request_id=?")->execute([time(),$admin['username'],$note,$id]);$pdo->prepare('INSERT INTO reseller_wallet_ledger(from_user_id,to_user_id,amount,reason,actor_reseller_id,created_at) VALUES(?,?,?,?,?,?)')->execute(['bank',(string)$r['reseller_id'],(int)$r['amount'],'reseller_deposit_approved',(string)$admin['id_admin'],time()]);$msg='✅ واریز شما تأیید شد و '.number_format((int)$r['amount']).' تومان به اعتبار نمایندگی اضافه شد.';}else{$pdo->prepare("UPDATE reseller_deposit_requests SET status='rejected',reviewed_at=?,reviewed_by=?,admin_note=? WHERE request_id=?")->execute([time(),$admin['username'],$note,$id]);$msg='❌ درخواست واریز شما رد شد.'.($note!==''?"\nدلیل: ".$note:'');}$pdo->prepare('INSERT INTO audit_log(admin_user,action,entity,details,ip,created_at) VALUES(?,?,?,?,?,?)')->execute([$admin['username'],'reseller_deposit.'.$act,$id,json_encode($r,JSON_UNESCAPED_UNICODE),redfox_client_ip(),date('c')]);$pdo->commit();try{sendmessage((string)$r['reseller_id'],$msg,null,'HTML');}catch(Throwable$ignore){}$flash='عملیات با موفقیت انجام شد.';}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();$flash=redfox_public_exception($e, 'panel/reseller_settlements.php');$ft='error';error_log('[reseller deposits] '.redfox_exception_fingerprint($e));}}
$rows=[];try{$rows=$pdo->query("SELECT * FROM reseller_deposit_requests ORDER BY (status='pending') DESC,created_at DESC LIMIT 500")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$flash='خطا در بارگذاری واریزها: '.redfox_public_exception($e, 'panel/reseller_settlements.php');$ft='error';}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>واریز نمایندگان</title><link rel="stylesheet" href="css/theme.css"></head><body><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">واریز و تسویه نمایندگان</h1><div class="page-head__sub">نماینده مبلغ را به حساب ادمین واریز می‌کند؛ پس از بررسی، اعتبار نمایندگی افزایش می‌یابد. شماره شبای نماینده لازم نیست.</div></div><?php if($flash):?><div class="card <?=$ft?>"><?=htmlspecialchars($flash)?></div><?php endif;?><div class="card"><div class="page-guide">شماره کارت‌های مقصد از بخش «کارت‌های بانکی» مدیریت می‌شوند. این صفحه فقط رسید واریزی نمایندگان را تأیید یا رد می‌کند.</div><div class="table-wrap"><table class="app-table"><tr><th>زمان شمسی</th><th>نماینده</th><th>مبلغ</th><th>شماره پیگیری</th><th>توضیح</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($rows as$r):?><tr><td><?=htmlspecialchars(rx_fa_date((int)$r['created_at']))?></td><td><code><?=htmlspecialchars($r['reseller_id'])?></code></td><td><?=number_format((int)$r['amount'])?> تومان</td><td><?=htmlspecialchars($r['payment_reference'])?></td><td><?=htmlspecialchars($r['note']??'—')?></td><td><?=$labels[$r['status']]??htmlspecialchars($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="request_id" value="<?=htmlspecialchars($r['request_id'])?>"><input name="admin_note" placeholder="توضیح ادمین"><button name="action" value="approve" class="btn btn-success">تأیید و افزایش اعتبار</button><button name="action" value="reject" class="btn btn-danger">رد درخواست</button></form><?php else:?><?=htmlspecialchars($r['admin_note']??'')?><?php endif;?></td></tr><?php endforeach;?></table></div></div></div></section></section></body></html>
